package ru.shield.shorts;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class LockActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setGravity(17);l.setPadding(40,40,40,40);l.setBackgroundColor(Color.rgb(20,20,26));TextView t=new TextView(this);t.setText("Лимит коротких видео закончился\n\nВернись завтра или введи PIN владельца");t.setTextColor(Color.WHITE);t.setTextSize(24);t.setGravity(17);l.addView(t);EditText p=new EditText(this);p.setInputType(2);p.setHint("PIN");l.addView(p);Button b1=new Button(this);b1.setText("Разблокировать на 10 минут");l.addView(b1);b1.setOnClickListener(v->{if(p.getText().toString().equals(getSharedPreferences("guard",0).getString("pin","")))finish();else Toast.makeText(this,"Неверный PIN",0).show();});setContentView(l);}public void onBackPressed(){} }
